<?php
require_once __DIR__ . '/config.php';
$pageTitle='Browse study resources';
$search=trim((string)($_GET['q']??''));$subjectId=valid_id($_GET['subject']??0);$categoryId=valid_id($_GET['category']??0);
$subjects=$pdo->query('SELECT id,name FROM subjects ORDER BY name')->fetchAll();$categories=$pdo->query('SELECT id,name FROM categories ORDER BY name')->fetchAll();
$sql="SELECT r.*,s.name subject_name,c.name category_name,u.name uploader,COALESCE(AVG(rr.rating),0) avg_rating,COUNT(DISTINCT rr.id) rating_count FROM resources r JOIN subjects s ON s.id=r.subject_id JOIN categories c ON c.id=r.category_id JOIN users u ON u.id=r.uploader_id LEFT JOIN resource_ratings rr ON rr.resource_id=r.id WHERE r.status='approved'";
$args=[];
if($search!==''){$sql.=" AND (r.title LIKE ? OR r.description LIKE ? OR s.name LIKE ?)";$like='%'.$search.'%';array_push($args,$like,$like,$like);}
if($subjectId){$sql.=" AND r.subject_id=?";$args[]=$subjectId;}if($categoryId){$sql.=" AND r.category_id=?";$args[]=$categoryId;}
$sql.=" GROUP BY r.id ORDER BY r.created_at DESC";$stmt=$pdo->prepare($sql);$stmt->execute($args);$resources=$stmt->fetchAll();
require __DIR__.'/includes/header.php';
?>
<section class="page-hero"><div class="container"><span class="eyebrow">THE SHARED LIBRARY</span><h1>Find your next useful resource.</h1><p>Browse approved notes, summaries, and study material. Filter by subject or category to get to what you need faster.</p></div></section>
<div class="page-content"><div class="container"><div class="resources-toolbar"><form class="search-form resource-filter-row" method="get"><input type="search" name="q" placeholder="Search notes, topics, subjects…" value="<?= e($search) ?>"><select name="subject" aria-label="Filter by subject"><option value="0">All subjects</option><?php foreach($subjects as $s): ?><option value="<?= (int)$s['id'] ?>" <?= $subjectId===(int)$s['id']?'selected':'' ?>><?= e($s['name']) ?></option><?php endforeach; ?></select><select name="category" aria-label="Filter by category"><option value="0">All categories</option><?php foreach($categories as $c): ?><option value="<?= (int)$c['id'] ?>" <?= $categoryId===(int)$c['id']?'selected':'' ?>><?= e($c['name']) ?></option><?php endforeach; ?></select><button class="btn btn-primary" type="submit">Search</button></form><?php if(current_user()): ?><a class="btn btn-outline upload-note-action" href="upload.php">＋ Upload note</a><?php endif; ?></div>
<?php if($resources): ?><div class="grid-3"><?php foreach($resources as $r): ?><article class="card resource-card"><span class="resource-type"><?= e($r['category_name']) ?></span><h3><a href="resource.php?id=<?= (int)$r['id'] ?>"><?= e($r['title']) ?></a></h3><p><?= e(excerpt($r['description'])) ?></p><div class="resource-meta"><span><?= e($r['subject_name']) ?></span><span>·</span><span><?= e(strtoupper($r['file_type'])) ?></span></div><div class="resource-meta"><span>By <?= e($r['uploader']) ?></span><span>·</span><span>⭐ <?= number_format((float)$r['avg_rating'],1) ?> (<?= (int)$r['rating_count'] ?>)</span></div><div class="card-actions"><a class="btn btn-outline btn-small" href="resource.php?id=<?= (int)$r['id'] ?>">View resource</a></div></article><?php endforeach; ?></div><?php else: ?><div class="empty-state"><div class="empty-icon">🔎</div><h3>No resources found</h3><p>Try another keyword or remove one of the filters. If you have a useful document, share it with your study community.</p><?php if(current_user()): ?><a class="btn btn-primary" href="upload.php">Upload a resource</a><?php endif; ?></div><?php endif; ?>
</div></div>
<?php require __DIR__.'/includes/footer.php'; ?>
